import React from 'react';
import {Html5Audio, interpolate, Sequence, staticFile} from 'remotion';
import type {HookConfig} from './hooks';
import {MUSIC_KEYS, SCENES} from './timing';
import {BUTTON_TAP, TYPE_END, TYPE_START} from './scenes/Scene3Solution';
import {RETAKE_TAP} from './scenes/Scene4Retake';

// Everything except the voice. All files are generated by `npm run sfx`
// (scripts/make-audio.mjs) – code-made, no stock. VO lives in voice.tsx.

const musicVolume = (f: number) =>
  interpolate(
    f,
    MUSIC_KEYS.map((k) => k[0]),
    MUSIC_KEYS.map((k) => k[1]),
    {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'},
  );

const Sfx: React.FC<{at: number; file: string; volume?: number; name?: string}> = ({at, file, volume = 0.6, name}) => (
  <Sequence from={at} durationInFrames={45} layout="none" name={name ?? `sfx ${file}`}>
    <Html5Audio src={staticFile(`sfx/${file}`)} volume={volume} />
  </Sequence>
);

export const Soundtrack: React.FC<{hook: HookConfig}> = ({hook}) => {
  const typingTaps: number[] = [];
  for (let f = TYPE_START; f < TYPE_END; f += 3) typingTaps.push(SCENES.solution.from + f);

  return (
    <>
      {/* phone-mic room tone under everything – sells "recorded at home" */}
      <Html5Audio src={staticFile('sfx/roomtone.wav')} volume={0.5} />

      {/* music bed with automation (silent in the hook, cut on the final laugh) */}
      <Html5Audio src={staticFile('music/bed.wav')} volume={(f) => musicVolume(f)} />

      {/* hook: pop on every counter slam */}
      {hook.counter.items.map((it, i) => (
        <Sfx key={`pop${i}`} at={it.at} file="pop.wav" volume={0.75} name={`pop counter ${i + 1}`} />
      ))}

      {/* whoosh on scene cuts */}
      {[SCENES.pain.from, SCENES.solution.from, SCENES.retake.from, SCENES.proof.from, SCENES.payoff.from].map((f) => (
        <Sfx key={`wh${f}`} at={f - 2} file="whoosh.wav" volume={0.35} />
      ))}

      {/* scene 3: soft taps while typing + button */}
      {typingTaps.map((f) => (
        <Sfx key={`tap${f}`} at={f} file="tap.wav" volume={0.35} />
      ))}
      <Sfx at={SCENES.solution.from + BUTTON_TAP} file="pop.wav" volume={0.5} />

      {/* scene 4: tiny ding on "צלם שוב רק את הקטע הזה" */}
      <Sfx at={SCENES.retake.from + RETAKE_TAP} file="ding.wav" volume={0.55} />
      <Sfx at={SCENES.retake.from + 100} file="pop.wav" volume={0.4} />

      {/* scene 5: timer slams at 00:00 */}
      <Sfx at={SCENES.proof.from + 80} file="ding.wav" volume={0.35} />

      {/* scene 7: one soft pop right before the loop point */}
      <Sfx at={805} file="pop.wav" volume={0.45} name="loop pop" />
    </>
  );
};
